1	import { describe, expect, it } from "vitest";
2	import { loadBalanceEvidence, resolveBalances } from "./balances";
3	import type { SupabaseClient } from "@supabase/supabase-js";
4	import { calendarDate, calendarDayBoundary, reviewedLocalTimestamp } from "./calendar";
5	
6	const accounts = [{ id: "cash", name: "Cash", currency_code: "EUR" }];
7	const snapshot = { id: "snapshot", account_id: "cash", amount_minor: "10000", currency_code: "EUR", as_of: "2026-09-28T12:00:00Z", provenance: "manual" };
8	const transaction = { id: "transaction", account_id: "cash", amount_minor: "-1250", currency_code: "EUR", posted_on: "2026-09-29", status: "posted" };
9	const now = "2026-10-01T12:00:00Z";
10	
11	it("loads active additional fees exactly once while retaining canonical source boundaries", async () => {
12	  const dated = { ...snapshot, as_of: "2026-10-01T08:00:00Z", boundary_kind: "after_transaction", source_transaction_id: "source" };
13	  const canonical = [
14	    { ...transaction, posted_at: dated.as_of, posted_on: "2026-10-01", transaction_sources: [{ source_transaction_id: "source" }] },
