12	export function reviewNetWorth(accountTotals: Record<string, string | null>, wealth: WealthValue[], today: string) {
13	  const dated = wealthEvidence(wealth, today);
14	  const currencies = [...new Set([...Object.keys(accountTotals), ...wealth.filter(row => !row.linked_account_id).map(row => row.currency_code)])];
15	  return Object.fromEntries(currencies.map(currency => {
16	    if (accountTotals[currency] === null || wealth.some(row => !row.linked_account_id && row.currency_code === currency && row.as_of > today)) return [currency, null];
17	    const total = BigInt(accountTotals[currency] ?? "0") + dated.included.filter(row => row.currencyCode === currency).reduce((sum, row) => sum + row.amountMinor, 0n);
18	    return [currency, total.toString()];
19	  }));
