5	type Snapshot = { account_id: string; amount_minor: string | number; currency_code: string; as_of: string; undone_at?: string | null };
6	type Valuation = { item_id: string; created_at: string; kind: string; amount_minor: string; currency_code: string; as_of: string; linked_account_id: string | null };
7	type Posting = { account_id: string; amount_minor: string | number; currency_code: string; posted_on: string; posted_at?: string | null; status: string };
8	type NetWorthPoint = { date: string; accounts: Map<string, bigint>; assets: Map<string, bigint>; debts: Map<string, bigint>; known: boolean };
9	export type CalculatedValue = { on_date: string; currency_code: string; total_minor: string };
10	
11	const add = (map: Map<string, bigint>, currency: string, amount: bigint) => map.set(currency, (map.get(currency) ?? 0n) + amount);
12	
13	// Month ends for the last `months` months, then today.
14	export function monthEnds(today: string, months: number): string[] {
15	  const [year, month] = today.split("-").map(Number);
16	  const dates = Array.from({ length: months }, (_, index) => new Date(Date.UTC(year, month - 1 - (months - 1 - index), 0)).toISOString().slice(0, 10));
17	  return [...dates, today];
18	}
19	
20	// Every calendar day from `from` to `to`, inclusive.
21	export function dayRange(from: string, to: string): string[] {
22	  const dates: string[] = [];
23	  for (let time = Date.parse(`${from}T00:00:00Z`), end = Date.parse(`${to}T00:00:00Z`); time <= end; time += 86400000) dates.push(new Date(time).toISOString().slice(0, 10));
24	  return dates;
25	}
