-- A Scalable sync writes the portfolio as wealth records (one per position, plus cash and crypto),
-- so net worth and its history use the existing valuation model. Each change is a wealth event
-- by the workspace owner, so history and undo work as for a hand-entered value.
-- portfolio keeps the latest totals, performance and synced item ids for display and removal.
alter table public.scalable_connections add column portfolio jsonb check (portfolio is null or jsonb_typeof(portfolio) = 'object');
grant select (portfolio) on public.scalable_connections to authenticated;

create function public.sync_scalable_wealth(p_connection_id uuid, p_items jsonb, p_portfolio jsonb) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; owner uuid; entry jsonb; previous public.wealth_items%rowtype; item public.wealth_items%rowtype;
  existing boolean; kept uuid[] := '{}'; changed integer := 0;
begin
  if p_connection_id is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_typeof(p_portfolio) is distinct from 'object' then
    raise exception 'Invalid Scalable sync' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  select owner_id into owner from public.workspaces where id = connection.workspace_id;
  for entry in select value from jsonb_array_elements(p_items) loop
    if entry - array['id','kind','name','currency_code','amount_minor','quantity_text','unit_price_text','cost_basis_minor','as_of'] <> '{}'::jsonb
      or entry->>'kind' not in ('holding','asset') then raise exception 'Unsupported Scalable wealth fields' using errcode = '22023'; end if;
    item := jsonb_populate_record(null::public.wealth_items, entry);
    if item.as_of > (now() at time zone coalesce((select timezone from public.workspace_settings where workspace_id = connection.workspace_id), 'Europe/Berlin'))::date then
      raise exception 'Valuation date cannot be in the future' using errcode = '22023'; end if;
    select * into previous from public.wealth_items where id = item.id for update;
    existing := found;
    if existing and previous.workspace_id <> connection.workspace_id then raise exception 'Wealth item belongs to another workspace' using errcode = '42501'; end if;
    if existing and (previous.kind <> item.kind or previous.currency_code <> item.currency_code) then raise exception 'Scalable position changed kind or currency' using errcode = '22023'; end if;
    kept := kept || item.id;
    if existing and previous.removed_at is null and previous.name = item.name and previous.amount_minor = item.amount_minor and previous.as_of = item.as_of
      and previous.quantity_text is not distinct from item.quantity_text and previous.unit_price_text is not distinct from item.unit_price_text
      and previous.cost_basis_minor is not distinct from item.cost_basis_minor then continue; end if;
    item.workspace_id := connection.workspace_id; item.version := coalesce(previous.version, 0) + 1; item.created_at := coalesce(previous.created_at, now());
    item.updated_at := now(); item.removed_at := null;
    insert into public.wealth_items select item.* on conflict (id) do update set name = excluded.name, amount_minor = excluded.amount_minor,
      quantity_text = excluded.quantity_text, unit_price_text = excluded.unit_price_text, cost_basis_minor = excluded.cost_basis_minor, as_of = excluded.as_of,
      version = excluded.version, removed_at = null, updated_at = excluded.updated_at;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), case when existing then public.wealth_record(previous) end, public.wealth_record(item));
    changed := changed + 1;
  end loop;
  -- Positions an earlier sync (from any connection of this workspace) wrote that Scalable no longer reports were sold.
  for previous in select w.* from public.wealth_items w where w.workspace_id = connection.workspace_id and w.removed_at is null and not (w.id = any(kept))
    and w.id in (select (jsonb_array_elements_text(c.portfolio->'itemIds'))::uuid from public.scalable_connections c where c.workspace_id = connection.workspace_id and c.portfolio ? 'itemIds')
    for update loop
    item := previous; item.removed_at := now(); item.version := previous.version + 1; item.updated_at := now();
    update public.wealth_items set removed_at = item.removed_at, version = item.version, updated_at = item.updated_at where id = item.id;
    insert into public.wealth_events(workspace_id, item_id, actor_id, request_id, before, after)
      values (connection.workspace_id, item.id, owner, gen_random_uuid(), public.wealth_record(previous), public.wealth_record(item));
    changed := changed + 1;
  end loop;
  update public.scalable_connections set portfolio = p_portfolio || jsonb_build_object('itemIds', to_jsonb(kept)), last_synced_at = now(), last_error = null
    where id = p_connection_id;
  return changed;
end;
$$;
revoke all on function public.sync_scalable_wealth(uuid, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.sync_scalable_wealth(uuid, jsonb, jsonb) to service_role;
-- Past Scalable values worked out from Scalable's own transactions and price charts. They are a calculation,
-- not a record, so they live apart from wealth_items and wealth_events: the event list stays the owner's real
-- history. Rows only exist for days before the first real synced value, and a run replaces all of them at once.
-- A disconnect keeps them, as it keeps synced wealth items; reset all data clears them.
create table public.scalable_value_history (
  workspace_id uuid not null references public.workspaces(id),
  on_date date not null,
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  securities_minor bigint not null,
  crypto_minor bigint not null,
  cash_minor bigint not null,
  total_minor bigint not null,
  primary key (workspace_id, on_date),
  check (total_minor = securities_minor + crypto_minor + cash_minor)
);
alter table public.scalable_value_history enable row level security;
create policy scalable_value_history_owner_select on public.scalable_value_history for select to authenticated using (public.owns_workspace(workspace_id));
revoke all on public.scalable_value_history from public, anon, authenticated;
grant select on public.scalable_value_history to authenticated;
grant all on public.scalable_value_history to service_role;

-- The outcome of the last calculation. Kept apart from last_error, which tells the owner a sync needs attention.
alter table public.scalable_connections add column history_status text check (history_status in ('ok','failed')),
  add column history_checked_on date,
  add column history_error text check (char_length(history_error) <= 1000);
grant select (history_status, history_checked_on) on public.scalable_connections to authenticated;

create function public.replace_scalable_value_history(p_connection_id uuid, p_rows jsonb, p_checked_on date) returns integer
language plpgsql security definer set search_path='' as $$
declare connection public.scalable_connections%rowtype; saved integer;
begin
  if p_connection_id is null or p_checked_on is null or jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'Invalid Scalable value history' using errcode = '22023'; end if;
  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
  delete from public.scalable_value_history where workspace_id = connection.workspace_id;
  insert into public.scalable_value_history(workspace_id, on_date, currency_code, securities_minor, crypto_minor, cash_minor, total_minor)
    select connection.workspace_id, row.on_date, row.currency_code, row.securities_minor, row.crypto_minor, row.cash_minor, row.total_minor
    from jsonb_to_recordset(p_rows) as row(on_date date, currency_code text, securities_minor bigint, crypto_minor bigint, cash_minor bigint, total_minor bigint);
  get diagnostics saved = row_count;
  update public.scalable_connections set history_status = 'ok', history_checked_on = p_checked_on, history_error = null where id = p_connection_id;
  return saved;
end;
$$;
revoke all on function public.replace_scalable_value_history(uuid, jsonb, date) from public, anon, authenticated;
grant execute on function public.replace_scalable_value_history(uuid, jsonb, date) to service_role;

create or replace function public.reset_workspace() returns void language plpgsql security definer set search_path='' as $$
declare ws uuid; owner uuid := auth.uid();
begin
  if owner is null then raise exception 'Unauthorized' using errcode='42501'; end if;
  select id into ws from public.workspaces where owner_id=owner for update;
  if not found then raise exception 'Workspace unavailable' using errcode='P0002'; end if;
  -- Deleted history is not undoable, so skip planning audit rows and link-edit guards.
  perform set_config('moneo.planning_undo','true',true);
  perform set_config('moneo.link_edit','on',true);

  -- Agent team runs, tasks and proposals.
  delete from public.agent_proposals where workspace_id=ws;
  delete from public.agent_tasks where workspace_id=ws;
  delete from public.agent_runs where workspace_id=ws;

  -- AI conversations and reviews.
  delete from public.saved_analyses where workspace_id=ws;
  delete from public.summary_runs where workspace_id=ws;
  delete from public.background_jobs where workspace_id=ws;
  delete from public.chat_requests where workspace_id=ws;
  delete from public.messages where workspace_id=ws;
  delete from public.conversations where workspace_id=ws;
  delete from public.dashboard_layouts where workspace_id=ws;

  -- Preferences, views and settings.
  delete from public.insight_dismissals where workspace_id=ws;
  delete from public.insight_preferences where workspace_id=ws;
  delete from public.financial_evidence_receipts where workspace_id=ws;
  delete from public.transaction_views where workspace_id=ws;
  delete from public.fx_rates where workspace_id=ws;
  delete from public.workspace_settings where workspace_id=ws;

  -- Everything that points at transactions.
  delete from public.transaction_link_fees where workspace_id=ws;
  delete from public.transaction_links where workspace_id=ws;
  delete from public.transaction_splits where workspace_id=ws;
  delete from public.transaction_split_sets where workspace_id=ws;
  delete from public.pending_hold_resolutions where workspace_id=ws;
  delete from public.correction_events where workspace_id=ws;
  delete from public.recurring_occurrence_settlements where workspace_id=ws;
  delete from public.recurring_series_transactions where workspace_id=ws;
  delete from public.recurring_series where workspace_id=ws;
  delete from public.manual_transaction_entries where workspace_id=ws;
  delete from public.money_metadata_events where workspace_id=ws;
  delete from public.organization_reviews where workspace_id=ws;
  delete from public.organization_rules where workspace_id=ws;
  delete from public.transaction_batches where workspace_id=ws;
  delete from public.scalable_value_history where workspace_id=ws;
  delete from public.wealth_events where workspace_id=ws;
  delete from public.wealth_items where workspace_id=ws;
  delete from public.transaction_sources where transaction_id in (select id from public.transactions where workspace_id=ws)
    or source_transaction_id in (select id from public.source_transactions where workspace_id=ws);
  delete from public.balance_snapshots where workspace_id=ws;
  update public.transactions set transfer_id=null, refund_of_id=null
    where workspace_id=ws and (transfer_id is not null or refund_of_id is not null);
  delete from public.transactions where workspace_id=ws;

  -- Bank connections, then imports.
  delete from public.bank_connection_accounts where workspace_id=ws;
  delete from public.bank_connections where workspace_id=ws;

  -- Imports.
  delete from public.source_transactions where workspace_id=ws;
  delete from public.import_control_events where workspace_id=ws;
  delete from public.import_staging where workspace_id=ws;
  delete from public.imports where workspace_id=ws;
  delete from public.data_sources where workspace_id=ws;

  -- Goals, plans, scenarios and budgets.
  delete from public.goal_reservation_events where workspace_id=ws;
  delete from public.goal_allocations where workspace_id=ws;
  delete from public.goal_events where workspace_id=ws;
  delete from public.goals where workspace_id=ws;
  delete from public.forecast_runs where workspace_id=ws;
  delete from public.scenario_overrides where workspace_id=ws;
  delete from public.scenario_events where workspace_id=ws;
  delete from public.scenarios where workspace_id=ws;
  delete from public.spending_plan_limits where workspace_id=ws;
  delete from public.spending_plans where workspace_id=ws;
  delete from public.financial_assumptions where workspace_id=ws;
  delete from public.planning_events where workspace_id=ws;
  delete from public.forecast_preference_events where workspace_id=ws;
  delete from public.forecast_preferences where workspace_id=ws;

  -- Remaining parents, then a fresh workspace exactly like create_private_workspace().
  delete from public.merchants where workspace_id=ws;
  delete from public.categories where workspace_id=ws;
  delete from public.accounts where workspace_id=ws;
  delete from public.workspaces where id=ws;
  insert into public.workspaces(owner_id) values(owner);
end;
$$;
revoke all on function public.reset_workspace() from public,anon;
grant execute on function public.reset_workspace() to authenticated;
-- Own money that arrives or leaves without an IBAN: a cash machine, Scalable Capital (its broker
-- withdrawals carry no IBAN), or an old account of the owner known only by their name on it.
-- Same audit as mark_own_account_transfer (operation own_account_transfer, no identifier), so
-- undo_own_account_transfer restores the row exactly.
--   cash      the bank's wording says cash machine; background jobs may mark it.
--   scalable  the owner connected Scalable; background jobs may mark it.
--   owner     only the signed-in owner, by accepting an own_transfer card (a name is weak evidence).
create function public.mark_own_named_transfer(
  p_transaction_id uuid,
  p_expected_version integer,
  p_kind text,
  p_label text default null
) returns public.transactions
language plpgsql security definer set search_path = '' as $$
declare
  actor uuid;
  old_row public.transactions%rowtype;
  new_row public.transactions%rowtype;
  own_label text;
begin
  if auth.uid() is null and (select auth.jwt()->>'role') is distinct from 'service_role' then raise exception 'Authentication required' using errcode = '28000'; end if;
  if p_kind is null or p_kind not in ('cash', 'scalable', 'owner') then raise exception 'Unknown own account' using errcode = '22023'; end if;
  if p_kind = 'owner' and auth.uid() is null then raise exception 'Only the owner can confirm this' using errcode = '42501'; end if;
  select * into old_row from public.transactions
  where id = p_transaction_id and public.can_link_workspace(workspace_id) for update;
  if not found then raise exception 'Transaction not found' using errcode = 'P0002'; end if;
  actor := public.link_actor(old_row.workspace_id);
  if p_kind = 'scalable' and not exists (select 1 from public.scalable_connections where workspace_id = old_row.workspace_id and status = 'active') then
    raise exception 'Scalable Capital is not connected' using errcode = '22023';
  end if;
  own_label := case p_kind when 'cash' then 'Cash' when 'scalable' then 'Scalable Capital' else btrim(coalesce(p_label, '')) end;
  if char_length(own_label) not between 1 and 120 then raise exception 'Name the own account' using errcode = '22023'; end if;
  if old_row.version is distinct from p_expected_version then
    raise exception 'Transaction changed; refresh and retry' using errcode = 'PT409';
  end if;
  if old_row.status <> 'posted' or old_row.kind <> 'ordinary' or old_row.transfer_id is not null or old_row.refund_of_id is not null
    or old_row.amount_minor = 0 or not (old_row.review_reasons <@ array['source_transfer']::text[])
    or exists (select 1 from public.transactions where refund_of_id = old_row.id or transfer_id = old_row.id)
    or exists (select 1 from public.transaction_split_sets where transaction_id = old_row.id and undone_at is null)
    or exists (select 1 from public.transaction_links where undone_at is null and (primary_transaction_id = old_row.id or counterpart_transaction_id = old_row.id))
  then raise exception 'Only posted, unlinked, unsplit transactions can be marked' using errcode = '22023'; end if;

  update public.transactions set kind = 'transfer', review_reasons = '{}', version = version + 1
  where id = old_row.id returning * into new_row;
  insert into public.correction_events (workspace_id, transaction_id, actor_id, before, after)
  values (old_row.workspace_id, old_row.id, actor,
    jsonb_build_object('category_id', old_row.category_id, 'note', old_row.note, 'kind', old_row.kind,
      'transfer_id', old_row.transfer_id, 'refund_of_id', old_row.refund_of_id,
      'review_reasons', to_jsonb(old_row.review_reasons), 'version', old_row.version),
    jsonb_build_object('category_id', new_row.category_id, 'note', new_row.note, 'kind', new_row.kind,
      'transfer_id', new_row.transfer_id, 'refund_of_id', new_row.refund_of_id,
      'review_reasons', to_jsonb(new_row.review_reasons), 'version', new_row.version,
      'operation', 'own_account_transfer', 'identifier_id', null, 'own_account', own_label, 'rule', p_kind));
  return new_row;
end;
$$;

revoke all on function public.mark_own_named_transfer(uuid, integer, text, text) from public, anon;
