  console.log("RETURN pairs", pairs.length, "unmatched", pairs.filter(p => !p.wd).length, "amount mismatch", pairs.filter(p => p.wd && p.a !== -p.wa).length, "maxGapDays", Math.max(...pairs.map(p => Math.abs(Date.parse(p.retDay) - Date.parse(p.wdDay)) / 864e5)), "return before withdrawal", pairs.filter(p => p.retDay < p.wdDay).length);
