  console.log("--- month ends shown->fixed"); for (const p of pts) if (new Date(Date.parse(p.d) + 864e5).getUTCDate() === 1 || p.d === today) console.log(p.d, eur(p.shown), eur(p.fixed), p.shown === p.fixed ? "" : `diff ${eur(p.fixed - p.shown)}`);
  console.log("--- moves >=150 after fix"); let prev = pts[0]; for (const p of pts.slice(1)) { if (Math.abs(p.fixed - prev.fixed) >= 15000) console.log(p.d, "fixed", eur(prev.fixed), "->", eur(p.fixed), "move", eur(p.fixed - prev.fixed), "shown", eur(p.shown), "bankmove", eur(p.bank - prev.bank), "assetmove", eur(p.assets - prev.assets)); prev = p; }
  console.log("--- June"); for (const p of pts) if (p.d >= "2026-05-28" && p.d <= "2026-07-02") console.log(p.d, "shown", eur(p.shown), "fixed", eur(p.fixed), "bank", eur(p.bank), "assets", eur(p.assets));
}
