const steps = [{ account_id: "a", amount_minor: 1000, currency_code: "EUR", as_of: "2026-10-31T23:00:00Z" }, { account_id: "a", amount_minor: 700, currency_code: "EUR", as_of: "2026-11-03T23:00:00Z" }];
